<script setup lang="ts">
const emit=defineEmits<{completed:[]}>()
import AccountQuizPanel from './AccountQuizPanel.vue'
import {ref,computed,watch,onBeforeUnmount,nextTick} from 'vue'
import {publishedQuiz,startGuestQuiz,submitGuestQuiz,type PublicQuiz,type QuizFeedback} from '@/api/quiz'
import {errorMessage} from '@/api/identity'
import {ApiError} from '@/api/client'
import {getGeneration,onRemoteIdentityChange} from '@/auth/token-session'
import {useAuthStore} from '@/stores/auth'
const props=defineProps<{article:string;version:string}>(),auth=useAuthStore()
const quiz=ref<PublicQuiz|null>(null),loading=ref(false),busy=ref(false),error=ref(''),loadError=ref(''),index=ref(0),choices=ref<Record<string,string>>({}),results=ref<Record<string,QuizFeedback>>({}),locked=ref(false),restartNeeded=ref(false),reloadNeeded=ref(false),token=ref('')
const question=computed(()=>quiz.value?.questions[index.value]),result=computed(()=>question.value?results.value[question.value.id]:undefined)
const legend=ref<HTMLLegendElement>()
const types:Record<string,string>={MAIN_IDEA:'主旨大意',DETAIL:'事实细节',INFERENCE:'推理判断',VOCABULARY:'词义猜测',ATTITUDE:'作者态度'}
let controller:AbortController|undefined,epoch=0,disposed=false
function valid(ticket:number,identity:number){return !disposed&&epoch===ticket&&getGeneration()===identity}
function settled(ticket:number,identity:number){if(disposed||epoch!==ticket)return;if(identity!==getGeneration()){clear();loadError.value='账户状态已变化，请重新加载练习。';return}busy.value=false;loading.value=false}
function clear(){epoch++;controller?.abort();token.value='';quiz.value=null;choices.value={};results.value={};index.value=0;busy.value=false;loading.value=false;error.value='';loadError.value='';locked.value=false;restartNeeded.value=false;reloadNeeded.value=false}
async function load(){clear();if(auth.user)return;const ticket=epoch,identity=getGeneration();controller=new AbortController();loading.value=true;try{const data=await publishedQuiz(props.article,props.version,controller.signal);if(valid(ticket,identity))quiz.value=data}catch(e){if(valid(ticket,identity)&&!(e instanceof DOMException&&e.name==='AbortError'))loadError.value=errorMessage(e)}finally{settled(ticket,identity)}}
async function submit(){if(busy.value||!question.value||!quiz.value||result.value||!choices.value[question.value.id])return;const q=question.value,ticket=epoch,identity=getGeneration(),choice=choices.value[q.id]!;busy.value=true;error.value='';locked.value=true;controller=new AbortController();try{if(!token.value){const session=await startGuestQuiz(props.article,props.version,quiz.value.versionId,controller.signal);if(!valid(ticket,identity))return;token.value=session.token}const response=await submitGuestQuiz(token.value,q.id,choice,controller.signal);if(valid(ticket,identity))results.value[q.id]=response}catch(e){if(valid(ticket,identity)){error.value=errorMessage(e);reloadNeeded.value=e instanceof ApiError&&e.code==='QUIZ_CHANGED';restartNeeded.value=e instanceof ApiError&&['QUIZ_SESSION_EXPIRED','QUIZ_CHANGED','QUIZ_SUBMISSION_CONFLICT'].includes(e.code??'')}}finally{settled(ticket,identity)}}
function next(){if(!result.value||!quiz.value||index.value>=quiz.value.questions.length-1)return;index.value++;locked.value=false;error.value='';void nextTick(()=>legend.value?.focus())}
function restart(){if(busy.value)return;token.value='';results.value={};index.value=0;locked.value=false;error.value='';restartNeeded.value=false}
const unsubscribe=onRemoteIdentityChange(()=>{clear();loadError.value='账户状态已变化，请重新加载练习。'})
watch(()=>[props.article,props.version,auth.user?.id],load,{immediate:true});onBeforeUnmount(()=>{disposed=true;clear();unsubscribe()})
</script>
<template><AccountQuizPanel v-if="auth.user" :article="article" :version="version" @completed="emit('completed')"/><details v-else class="article-quiz-panel"><summary><span>阅读理解</span><small>{{ loading?'正在加载':quiz?`${quiz.questions.length} 题`:'练习' }}</small></summary><div class="article-quiz-content"><p class="reader-rail-note">本轮为临时体验，提交后由服务端反馈答案；不保存个人成绩，也不计入打卡。刷新后重新开始。</p><p v-if="loading" role="status">正在加载练习…</p><div v-else-if="loadError" role="alert"><p>{{ loadError }}</p><button class="button-secondary" @click="load">重试加载练习</button></div><p v-else-if="!quiz" class="reader-rail-note">本篇暂未发布阅读题，仍可正常阅读和标记读完。</p><template v-else-if="question"><p class="quiz-position">第 {{ index+1 }} / {{ quiz.questions.length }} 题 · {{ types[question.type] }}</p><form @submit.prevent="submit"><fieldset :disabled="busy||locked||!!result"><legend ref="legend" tabindex="-1">{{ question.stem }}</legend><label v-for="(option,i) in question.options" :key="i" class="quiz-choice" :class="{selected:choices[question.id]==='ABCD'[i]}"><input v-model="choices[question.id]" type="radio" :name="`quiz-${quiz.versionId}-${question.id}`" :value="'ABCD'[i]"><span>{{ 'ABCD'[i] }}. {{ option }}</span></label></fieldset><p v-if="error" role="alert" class="auth-field-error">{{ error }}</p><div v-if="result" class="quiz-feedback" role="status"><strong>{{ result.correct?'回答正确':'再看一下原文' }} · 正确答案：{{ result.correctOption }}</strong><p>{{ result.explanation }}</p><p v-if="result.completed">本次正确 {{ result.correctCount }} / {{ result.total }}（{{ Math.round(result.correctCount/result.total*100) }}%）</p></div><div class="reading-actions"><button v-if="!result&&!restartNeeded" class="button-primary" :disabled="busy||!choices[question.id]">{{ busy?'正在提交…':error?'重试提交':'提交答案' }}</button><button v-if="result&&index<quiz.questions.length-1" type="button" class="button-primary" @click="next">下一题</button><button v-if="restartNeeded" type="button" class="button-secondary" :disabled="busy" @click="reloadNeeded?load():restart()">重新开始体验</button><button v-if="result?.completed" type="button" class="button-secondary" @click="restart">重新体验</button></div></form></template></div></details></template>
